/* Generated by scripts/brand.py — the Runfold mark in the active skin's
   colours: three discs through each other's centres (the reading levels),
   their common core a Reuleaux triangle pointing right (Run). */

const MARK = `<defs><clipPath id="rf-hdr0"><circle cx="63.279" cy="50" r="30.667"/></clipPath><clipPath id="rf-hdr1"><circle cx="36.721" cy="65.333" r="30.667"/></clipPath><clipPath id="rf-hdr2"><circle cx="36.721" cy="34.667" r="30.667"/></clipPath></defs><circle cx="63.279" cy="50" r="30.667" style="fill:var(--ink)"/><circle cx="36.721" cy="65.333" r="30.667" style="fill:color-mix(in oklab, var(--ink) 45%, var(--accent))"/><circle cx="36.721" cy="34.667" r="30.667" style="fill:var(--accent-ink)"/><g clip-path="url(#rf-hdr0)"><circle cx="36.721" cy="65.333" r="30.667" style="fill:color-mix(in oklab, color-mix(in oklab, var(--ink) 50%, color-mix(in oklab, var(--ink) 45%, var(--accent))) 84%, black)"/></g><g clip-path="url(#rf-hdr1)"><circle cx="36.721" cy="34.667" r="30.667" style="fill:color-mix(in oklab, color-mix(in oklab, color-mix(in oklab, var(--ink) 45%, var(--accent)) 50%, var(--accent-ink)) 84%, black)"/></g><g clip-path="url(#rf-hdr2)"><circle cx="63.279" cy="50" r="30.667" style="fill:color-mix(in oklab, color-mix(in oklab, var(--accent-ink) 50%, var(--ink)) 84%, black)"/></g><g clip-path="url(#rf-hdr0)"><g clip-path="url(#rf-hdr1)"><circle cx="36.721" cy="34.667" r="30.667" style="fill:var(--accent)"/></g></g>`;

export function RunfoldMark({ className }: { className?: string }) {
  return <svg viewBox="0 0 100 100" className={className} aria-hidden dangerouslySetInnerHTML={{ __html: MARK }} />;
}
